import java.io.*;
import java.nio.file.*;
import java.util.*;

public class StowRun {
  static class Plan {
    List<byte[]> parts = new ArrayList<>();
    List<String> keys = new ArrayList<>();
    long reused;
  }

  static Plan manifestPlan(byte[] src, String name, Map<String,String> idx) throws Exception {
    Path mk = Paths.get("/app/urnbay/marks/" + name + ".m");
    if (!Files.exists(mk)) return null;
    Plan p = new Plan();
    ByteArrayOutputStream all = new ByteArrayOutputStream();
    for (String line : Files.readAllLines(mk)) {
      String key = line.trim();
      if (key.isEmpty()) continue;
      String rel = idx.get(key);
      if (rel == null) return null;
      byte[] piece = Idx.blob(rel);
      p.keys.add(key);
      p.parts.add(piece);
      all.write(piece);
    }
    if (!Arrays.equals(src, all.toByteArray())) return null;
    p.reused = src.length;
    return p;
  }

  static Plan completeStoredPlan(byte[] src, Gear g, Map<String,String> idx) throws Exception {
    Plan p = new Plan();
    p.parts = Slice.cut(src, g.mask, g.min, g.max);
    for (byte[] piece : p.parts) {
      String key = Seal.pay(piece);
      if (!idx.containsKey(key)) return null;
      p.keys.add(key);
      p.reused += piece.length;
    }
    return p;
  }

  static Plan livePlan(byte[] src, Gear g, Map<String,String> idx) throws Exception {
    Plan p = new Plan();
    p.parts = Slice.cut(src, g.mask, g.min, g.max);
    for (byte[] piece : p.parts) {
      String key = Seal.pay(piece);
      p.keys.add(key);
      if (idx.containsKey(key)) p.reused += piece.length;
    }
    return p;
  }

  public static int run(String reel) throws Exception {
    byte[] src = Files.readAllBytes(Paths.get(reel));
    String name = Paths.get(reel).getFileName().toString();
    Map<String,String> idx = Idx.load();
    Gear live = Gear.load("/app/gearpit/live.gear");

    Plan plan = manifestPlan(src, name, idx);
    if (plan == null) {
      Path legacyPath = Paths.get("/app/gearpit/legacy.gear");
      if (Files.exists(legacyPath))
        plan = completeStoredPlan(src, Gear.load(legacyPath.toString()), idx);
    }
    if (plan == null) plan = livePlan(src, live, idx);

    long stored = 0;
    Path hot = Paths.get("/app/urnbay/hot");
    Files.createDirectories(hot);
    for (int i = 0; i < plan.parts.size(); i++) {
      byte[] piece = plan.parts.get(i);
      String key = plan.keys.get(i);
      if (!idx.containsKey(key)) {
        String rel = "hot/" + key + ".blob";
        Files.write(hot.resolve(key + ".blob"), piece);
        Idx.put(key, rel);
        idx.put(key, rel);
        stored += piece.length;
      }
    }

    Path flag = Paths.get("/app/urnbay/marks/" + name + ".flag");
    boolean prior = Files.exists(flag);
    Path mk = Paths.get("/app/urnbay/marks/" + name + ".m");
    Files.createDirectories(mk.getParent());
    Files.writeString(mk, String.join("\n", plan.keys) + (plan.keys.isEmpty() ? "" : "\n"));

    double reuse = src.length == 0 ? 1.0 : plan.reused / (double)src.length;
    double mean = plan.parts.isEmpty() ? 0.0 : src.length / (double)plan.parts.size();
    String json = "{\n"
      + "  \"reel\": \"" + name + "\",\n"
      + "  \"bytes_in\": \"" + src.length + "\",\n"
      + "  \"bytes_stored\": \"" + stored + "\",\n"
      + "  \"reuse_frac\": \"" + String.format(Locale.US, "%.4f", reuse) + "\",\n"
      + "  \"mean_piece\": \"" + String.format(Locale.US, "%.4f", mean) + "\",\n"
      + "  \"piece_count\": \"" + plan.parts.size() + "\"\n"
      + "}\n";
    Files.writeString(Paths.get("/app/urnbay/tally.json"), json);
    Files.writeString(Paths.get("/app/urnbay/last.json"), json);
    Floor.ok(reuse);
    if (prior && stored == src.length && src.length > 0) return 1;
    Files.writeString(flag, "1\n");
    return 0;
  }
}
